static bool PairCase(string first, string second, int a, int b, bool cancel = false, bool fail = false, bool cancelDuring = false)
{
    using var stop = new System.Threading.CancellationTokenSource();
    if (cancel) stop.Cancel();
    PairSource.Reset(stop.Token);
    var pending = Practice.TotalTogetherAsync(first, second, stop.Token);
    if (PairSource.Shops.Count != 2 || PairSource.Shops[0] != first || PairSource.Shops[1] != second || !PairSource.TokensMatch) return false;
    // Both reads must have started before the checks provide either result.
    if (cancelDuring) stop.Cancel();
    else if (!cancel) PairSource.Complete(a, b, fail);
    try { return pending.GetAwaiter().GetResult() == a + b && !cancel && !cancelDuring && !fail; }
    catch (OperationCanceledException) { return (cancel || cancelDuring) && pending.IsCanceled; }
    catch (InvalidOperationException error) { return fail && error.Message == "Source is offline."; }
}
